set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {DatabaseSync} from 'node:sqlite';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {ThreeFlowState} from './src/newsFlow/threeFlowState.mjs';import {parseConfiguredArticle} from './src/web/configurableNewsParser.mjs';import {requestKey,articleKey} from './src/newsFlow/identity.mjs';import {originalPublicationContract} from './src/web/newsOriginalPublicationContract.mjs';const root='/var/lib/news-flow/qc-recover25-20261122',r=JSON.parse(fs.readFileSync(root+'/cnn-final-failures.json')),registry=await loadNewsRegistry(),source=registry.sources.get('edition.cnn.com'),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite'),state=new ThreeFlowState(db),out={at:new Date().toISOString(),closed:[]};db.exec('PRAGMA busy_timeout=5000');state.configureSites(registry.sources.values());try{for(const p of r.rows){if(p.url!=='https://www.cnn.com/2026/11/19/us/iowa-chemicals-lead-detonation')continue;const html=gunzipSync(fs.readFileSync(p.file)).toString(),parsed=parseConfiguredArticle(html,p.url,{...source.config,nativePublicationAdapter:undefined});assert(!parsed.error);assert(originalPublicationContract(parsed.extracted.publicationProof));assert.equal(parsed.extracted.publisherRestricted,true);assert.equal(parsed._source.publishedDate,'2026-11-19T12:48:38.555Z');assert(Date.now()-Date.parse(parsed._source.publishedDate)>24*3600000);const key=articleKey(p.url),checkedAt=Date.parse(r.at),now=Date.now(),result=state.tx(()=>{const row=db.prepare('SELECT * FROM article_links WHERE parse_key=?').get(key),failure=db.prepare('SELECT * FROM url_failures WHERE url_key=?').get(requestKey(p.url));if(row?.parse_status!=='fail'||row.error!=='CNN_LITE_PUBLIC_BODY_NOT_VERIFIED'||failure?.last_at>checkedAt)return {changed:0};const update=db.prepare("UPDATE article_links SET parse_status='skipped',error='outside_new_article_window',reviewed_at=? WHERE parse_key=? AND parse_status='fail' AND error=?").run(now,key,row.error);db.prepare("DELETE FROM url_failures WHERE url_key=? AND site=? AND role='article' AND last_at<=?").run(requestKey(p.url),'edition.cnn.com',checkedAt);state.remember({site:source.domain,url:p.url,url_key:requestKey(p.url)},'done','outside_new_article_window',now);state.event('manual_expired_native_article_review',{site:source.domain,url:p.url,publishedDate:parsed._source.publishedDate,publicationProof:parsed.extracted.publicationProof,nativeHtmlSha256:createHash('sha256').update(html).digest('hex'),accessFlagRetained:true,noEsWrite:true,reason:'outside_new_article_window'});return {changed:update.changes};});out.closed.push({url:p.url,publishedDate:parsed._source.publishedDate,publicationProof:parsed.extracted.publicationProof,...result,noEsWrite:true});}fs.writeFileSync(root+'/cnn-expired-closeout.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out));}finally{state.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-recover25-20261122/cnn-expired-closeout.json "$upload_dir/.qc-recover25-cnn-expired-closeout.json"
